// Loaded by goal-public-runtime-N.test.mjs (one shard each) and by
// goal-public-runtime-all.mjs (every test, used by the producer subprocesses).
const test = (name, ...rest) => goalRuntimeShardAdmits(name) ? nodeTest(name, ...rest) : undefined;

// The Goal runtime unrefs its background timers (stop polling, channel
// retirement) so they never keep a Pi host alive. A real host stays alive while
// a Goal runs; without this, Node 22's test runner cancels a test whose pending
// work waits only on those timers ("event loop has already resolved"). Node 24
// already keeps the loop alive. Test deadlines still bound every scenario.
const hostAlive = setInterval(() => {}, 2 ** 30);
after(() => clearInterval(hostAlive));

/** The SDK's own agent-core instance: nested under pi-coding-agent in older
 * installs, hoisted beside it in current ones. */
async function importPiAgentCore() {
  const nested = new URL("../node_modules/@earendil-works/pi-agent-core/dist/index.js",
    import.meta.resolve("@earendil-works/pi-coding-agent"));
  if (existsSync(nested)) return import(nested.href);
  return import("@earendil-works/pi-agent-core");
}

function candidateReadHex(result) {
  assert.equal(result.status, "ok");
  assert.equal(result.page.eof, true, "the short fixture must be read completely");
  assert.ok(["utf8", "base64"].includes(result.page.encoding));
  const bytes = Buffer.from(result.page.content, result.page.encoding);
  assert.equal(bytes.length, result.page.returnedBytes);
  return bytes.toString("hex");
}

