test("child profile exception candidate bridge predicate admits only exact unselected custody", () => {
  const worker = {};
  const preparation = { attemptKey: "attempt" };
  const attempts = new Map([["attempt", preparation]]);
  const channel = {};
  const bridge = {
    selectedKey: "selected",
    candidates: new Map([["sibling", { worker, preparation, attemptKey: "attempt", attempts, channel }]]),
  };
  const original = {
    bridge,
    currentBridge: bridge,
    key: "sibling",
    worker,
    preparation,
    attemptKey: "attempt",
    attempts,
    channel,
    currentWorker: worker,
    currentPreparation: preparation,
    currentAttempts: attempts,
    currentChannel: channel,
  };
  assert.equal(childProfileExceptionCandidateBridgeMatches(original), true);
  for (const [name, changed] of [
    ["selected", { key: "selected" }],
    ["worker", { currentWorker: {} }],
    ["preparation", { currentPreparation: { attemptKey: "attempt" } }],
    ["attempt map", { currentAttempts: new Map([["attempt", preparation]]) }],
    ["channel", { currentChannel: {} }],
    ["attempt", { attemptKey: "other-attempt" }],
    ["registry", { currentBridge: { ...bridge } }],
  ]) {
    assert.equal(childProfileExceptionCandidateBridgeMatches({ ...original, ...changed }), false,
      `changed ${name} custody is denied`);
  }
});

test("child profile exception selected candidate guard fails closed beyond worker-only custody", () => {
  const prepared = {}, worker = { prepared, generation: 1 };
  const preparation = { prepared, generation: 1, attemptKey: "attempt" };
  const attempts = new Map([["attempt", preparation]]);
  const channel = {};
  assert.equal(childProfileExceptionSelectedCandidateInFlight({
    worker, preparation, attempts, channel,
  }), true, "selected candidate preparation/channel blocks transition activation");
  assert.equal(childProfileExceptionSelectedCandidateInFlight({
    worker, preparation: undefined, attempts: undefined, channel: undefined,
  }), false, "unlaunched worker binding alone is not an in-flight candidate channel");
  assert.equal(childProfileExceptionSelectedCandidateInFlight({
    worker, preparation, attempts: new Map(), channel,
  }), true, "missing primitive attempt entry blocks reconfiguration under corrupted selected custody");
  assert.equal(childProfileExceptionSelectedCandidateInFlight({
    worker, preparation, attempts: new Map([["other-attempt", preparation]]), channel,
  }), true, "mismatched primitive attempt entry blocks reconfiguration under corrupted selected custody");
  assert.equal(childProfileExceptionSelectedCandidateInFlight({
    worker, preparation: undefined, attempts: undefined, channel,
  }), true, "selected candidate channel without preparation blocks reconfiguration");
  assert.equal(childProfileExceptionSelectedCandidateInFlight({
    worker, preparation, attempts: undefined, channel: undefined,
  }), true, "selected candidate preparation without channel blocks reconfiguration");
});

test("profile exception bridge observation refreshes disappearance and denies replacement", () => {
  const bridge = {}, replacement = {};
  assert.equal(profileExceptionBridgeObservation({ pinned: bridge, live: bridge }), "same",
    "stale-successful reads remain usable only while the pinned bridge remains live");
  assert.equal(profileExceptionBridgeObservation({ pinned: bridge, live: undefined }), "refresh",
    "pinned bridge disappearance forces one complete fresh observation even without a stale assertion failure");
  assert.equal(profileExceptionBridgeObservation({ pinned: bridge, live: replacement }), "replacement",
    "replacement appearing during an awaited read is denied");
  assert.equal(profileExceptionBridgeObservation({ pinned: undefined, live: bridge }), "pin",
    "the first live bridge observed after no-bridge entry is pinned for the invocation");
});

async function sendCandidateAndLoseAck(binding, data) {
  const ssh2 = (await import("ssh2")).default;
  const client = new ssh2.Client();
  const payload = data;
  const operationId = data.toolCallId;
  const fingerprint = goalHash({ tool: data.tool, params: data.params });
  const nonce = randomBytes(24).toString("hex");
  const frame = (phase, value) => {
    const envelope = { version: 1, attemptKey: binding.attemptKey, channelId: binding.channelId,
      operationId, fingerprint, nonce, phase, payload: value,
      digest: createHash("sha256").update(JSON.stringify(value)).digest("hex") };
    const body = Buffer.from(JSON.stringify(envelope)), prefix = Buffer.allocUnsafe(4);
    prefix.writeUInt32BE(body.length);
    return Buffer.concat([prefix, body]);
  };
  const socket = connectUnix({ path: binding.socketPath });
  const clientClosed = new Promise(resolve => client.once("close", resolve));
  const socketClosed = new Promise(resolve => socket.once("close", resolve));
  try {
    await new Promise((resolve, reject) => {
      client.on("error", reject); socket.on("error", reject);
      client.once("ready", () => client.subsys("pi-workflow-goal-v1", (error, stream) => {
        if (error) { reject(error); return; }
        stream.on("error", reject);
        stream.once("data", () => { stream.destroy(); client.end(); resolve(); });
        stream.write(frame("request", payload));
      }));
      client.connect({ sock: socket, username: "goal-local",
      password: binding.secret, authHandler: ["password"], algorithms: { serverHostKey: ["ssh-ed25519"] },
      hostVerifier: key => createHash("sha256").update(key).digest("hex") === binding.hostKeyPin, readyTimeout: 30_000 });
    });
  } finally {
    socket.destroy(); client.end();
    await Promise.all([clientClosed, socketClosed]);
  }
}

test("ordinary Goal summary preserves stopping and unknown usage without mutating evidence", async () => {
  const { summarizeOrdinaryWorkflowGoal } = await import("../../.tmp/unit/goal-workflow-commands.js");
  for (const [observedUsage, expectedUsage] of [
    ["UNKNOWN", "Tokens: unknown"],
    [{ totalTokens: 0, costUsd: 0, tasksReporting: 0, taskCount: 1 },
      "Tokens: 0 (some tasks did not report usage)"],
    [{ totalTokens: NaN, costUsd: Infinity, tasksReporting: 1, taskCount: 1 },
      "Tokens: unknown"],
  ]) {
    const data = {
      runId: "workflow_summary_fixture", runStatus: "running", observedUsage,
      currentWork: [{ specId: "candidate", status: "running" }, { specId: "verification", status: "blocked" }],
      policies: [{
        goalId: "goal_summary_fixture", state: "cancellation_pending", taskStatus: "running", generation: 2,
        statusDetail: "Stopping: original descendant drain remains UNKNOWN",
        importantFailureOrUnknown: null,
        criteria: ["met", "not-met", "pending", "unknown"].map(verdict => ({ verdict })),
        originalProfile: { name: "captured" },
        originalDefinition: { privateDetails: "DO_NOT_EXPAND_DEFINITION_IN_SUMMARY" },
        exactEvidenceAvailability: "unavailable/UNKNOWN",
        usage: { requests: null, costMicros: null },
      }],
    };
    const before = structuredClone(data);
    const summary = summarizeOrdinaryWorkflowGoal(data);
    const lines = summary.split("\n");
    assert.equal(lines[0], "Goal (workflow_summary_fixture) — running", "a stopping run with a pending criterion is not waiting for judgment");
    assert.ok(lines.includes("Criteria: 1 of 4 met, 1 not met, 1 waiting for your judgment, 1 unknown (no verified evidence)"));
    assert.ok(lines.includes("Used: attempts 3 · request count when the Goal finishes · cost not reported"),
      "no total is invented for an unfinished Goal");
    assert.ok(lines.includes("Why: Stopping: original descendant drain remains UNKNOWN"));
    assert.ok(lines.includes("Now: candidate running, verification blocked"));
    assert.ok(lines.includes(expectedUsage), summary);
    assert.equal(lines.at(-1), "Next: pause: /workflow goal pause workflow_summary_fixture");
    assert.doesNotMatch(summary, /DO_NOT_EXPAND_DEFINITION_IN_SUMMARY/);
    assert.ok(summary.length < 2000);
    assert.deepEqual(data, before, "formatting must not change the supplied persisted observation");
  }
});

