/**
 * Test-only watchdog scale. Internal waits and per-test timeouts here are
 * liveness guards, not performance assertions; under heavy machine load they
 * expire although the behaviour is correct. PIWF_TEST_TIME_FACTOR (1-10) wins.
 * Otherwise an internal wait follows the one-minute load per CPU when it
 * starts (capped at 3), and a per-test timeout always uses the cap: a correct
 * test is never slower for it, and a load spike after the file started can no
 * longer time it out.
 */
const envTimeFactor = (() => {
  if (process.env.PIWF_TEST_TIME_FACTOR === undefined) return undefined;
  const factor = Number(process.env.PIWF_TEST_TIME_FACTOR);
  assert.ok(Number.isFinite(factor) && factor >= 1 && factor <= 10, "PIWF_TEST_TIME_FACTOR must be 1-10");
  return factor;
})();
const loadTimeFactor = () =>
  Math.min(3, Math.max(1, Math.round(osLoadAverage()[0] / Math.max(1, osCpuCount()) * 10) / 10));
const testMs = ms => Math.ceil(ms * (envTimeFactor ?? loadTimeFactor()));
const testTimeoutMs = ms => Math.ceil(ms * (envTimeFactor ?? 3));

/**
 * When a Goal test fails or times out, fence every Goal host session it
 * installed so its live runs' channels drain and the test file can still
 * finish. Create it before the test's other teardown: after hooks run in
 * registration order, and passing tests keep their own stop/teardown order.
 */
function goalSessionFence(t) {
  const shutdowns = [];
  t.after(async () => {
    if (t.passed) return;
    await Promise.allSettled(shutdowns.map(shutdown => shutdown()));
  });
  return {
    own(handler, context = () => ({})) {
      if (typeof handler !== "function") return;
      let closing;
      shutdowns.push(() => closing ??= Promise.resolve().then(() =>
        handler({ type: "session_shutdown", reason: "quit" }, context())));
    },
  };
}

/**
 * Goal consent as a person uses it in the TUI: read the one-screen summary,
 * open the full details, then run or cancel. `decide(title, preview)` sees the
 * full preview the consent is bound to.
 */
/** Full views of Goal judgments opened through "Show everything", newest last. */
const goalJudgmentViews = [];

function goalConsentUi(ui, decide) {
  let opened;
  return { ...ui,
    // A Goal consent must go through the summary flow, never the plain fallback.
    async confirm(title, text) {
      assert.doesNotMatch(title, /^Confirm Goal/, "Goal consent fell back to the plain confirmation");
      return ui.confirm(title, text);
    },
    async select(title, options) {
      const match = /^(Confirm Goal (?:execution|profile exception))\n/.exec(title);
      if (!match) return ui.select(title, options);
      assert.ok(title.split("\n").length <= 40, `the consent summary fits on one screen:\n${title}`);
      assert.deepEqual(options.slice(1), ["Show full details", "Cancel"]);
      if (!opened) return "Show full details";
      const preview = opened; opened = undefined;
      return (await decide(match[1], preview)) ? options[0] : "Cancel";
    },
    // Full details open in a read-only viewer that starts at the top.
    custom(factory) {
      return new Promise(resolve => {
        let component;
        const done = value => { component?.dispose?.(); resolve(value); };
        component = factory({ requestRender() {}, terminal: { rows: 40 } }, { fg(_role, value) { return value; }, bold: value => value },
          undefined, done);
        if (typeof component?.title === "string" && component.title.startsWith("Goal judgment")) {
          goalJudgmentViews.push(component.text);
          component.handleInput("\u001b");
          return;
        }
        if (typeof component?.title !== "string" || !component.title.startsWith("Confirm Goal")) return;
        assert.match(component.title, /^Confirm Goal (?:execution|profile exception): full details/);
        const marker = "Exact preview this consent is bound to (JSON)\n";
        assert.ok(component.text.includes(marker), "full details end with the exact bound preview");
        assert.doesNotMatch(component.text.slice(0, component.text.lastIndexOf(marker)), /"executionFoundation"/,
          "the readable part is not raw JSON");
        const firstPage = component.render(120).join("\n");
        assert.match(firstPage, /^ (Goal: |Run: )/m, "the viewer opens at the top, on the readable part");
        opened = JSON.parse(component.text.slice(component.text.lastIndexOf(marker) + marker.length));
        component.handleInput("\u001b");
      });
    },
  };
}

/**
 * Teardown join for a failed test. A failure can leave a fake native callback
 * that never settles; an unbounded join then keeps the whole test file from
 * finishing. Passing tests still join without a bound.
 */
async function joinAfterFailure(t, label, work, ms = testMs(30_000)) {
  if (t.passed === true) return await work;
  let timer;
  try {
    return await Promise.race([work, new Promise(resolve => {
      timer = setTimeout(() => {
        console.error(`TEST_ONLY ${label} did not settle ${ms}ms after a failure; teardown continues, evidence retained`);
        resolve(undefined);
      }, ms);
    })]);
  } finally { clearTimeout(timer); }
}

/**
 * A denial must not touch the parent Goal run, but the engine keeps scheduling
 * it meanwhile (for example a Goal task waiting on its child moves between
 * running and pending). Compare everything except those scheduling fields.
 */
function assertParentGoalCustodyUnchanged(afterBytes, beforeBytes, message = "parent Goal run custody unchanged") {
  const custody = bytes => {
    const run = JSON.parse(Buffer.from(bytes).toString("utf8"));
    delete run.updatedAt; delete run.taskSummary;
    for (const task of run.tasks ?? [])
      for (const key of ["status", "statusDetail", "lastMessage", "startedAt", "completedAt", "updatedAt"]) delete task[key];
    return run;
  };
  assert.deepEqual(custody(afterBytes), custody(beforeBytes), message);
}

const originalEndpoints = new WeakMap();
async function captureOriginalEndpoint(callback, socketPath) {
  assert.equal(originalEndpoints.has(callback), false, "original callback cannot be rebound");
  const identity = await lstat(socketPath);
  assert.equal(identity.isSocket(), true, "capture requires the original live Unix endpoint");
  originalEndpoints.set(callback, Object.freeze({ socketPath, dev: identity.dev, ino: identity.ino }));
  return callback;
}

async function assertOriginalCandidateRetired(callback, args, message) {
  const original = originalEndpoints.get(callback);
  assert.ok(original, "retirement requires original callback endpoint capture");
  // A closed server is no longer guard-allowlisted. Observe actual endpoint
  // absence instead of mistaking the guard's refusal for a kernel rejection.
  await assert.rejects(lstat(original.socketPath), { code: "ENOENT" },
    `${message}: original socket ${original.dev}/${original.ino} must be absent`);
  await assert.rejects(callback(...args), { code: /^(ENOENT|ECONNREFUSED)$/ }, message);
}

async function waitForOriginalEndpointRetirement(callback, signal) {
  const original = originalEndpoints.get(callback);
  assert.ok(original, "retirement requires original callback endpoint capture");
  await new Promise((resolveWait, reject) => {
    let watcher, poll;
    const finish = error => {
      watcher?.close();
      clearInterval(poll);
      signal.removeEventListener("abort", abort);
      if (error) reject(error); else resolveWait();
    };
    const abort = () => finish(signal.reason);
    const inspect = () => {
      try {
        const current = lstatSync(original.socketPath);
        assert.equal(current.isSocket(), true, "replacement file is not original retirement");
        assert.deepEqual([current.dev, current.ino], [original.dev, original.ino],
          "replacement endpoint is not original retirement");
      } catch (error) {
        if (error.code === "ENOENT") finish();
        else finish(error);
      }
    };
    // A drained channel also removes its private socket directory; an absent
    // directory is the same retirement as an absent endpoint. Directory watches
    // can miss events once the watched directory itself is removed, so poll too.
    poll = setInterval(inspect, 50);
    try { watcher = watch(dirname(original.socketPath), inspect); }
    catch (error) {
      if (error.code === "ENOENT") { inspect(); return; }
      throw error;
    }
    watcher.once("error", finish);
    signal.addEventListener("abort", abort, { once: true });
    if (signal.aborted) abort(); else inspect();
  });
}

test("physical candidate retirement observer rejects live replaced and unbound endpoints", async t => {
  const directory = await mkdtemp(join(tmpdir(), "goal-endpoint-observer-"));
  const socketPath = join(directory, "candidate.sock");
  const server = createUnixServer();
  t.after(async () => {
    if (server.listening) await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
    await rm(directory, { recursive: true, force: true });
  });
  await new Promise((resolve, reject) => { server.once("error", reject); server.listen(socketPath, resolve); });
  const callback = await captureOriginalEndpoint(() => lstat(socketPath), socketPath);
  await assert.rejects(assertOriginalCandidateRetired(callback, [], "live"), { code: "ERR_ASSERTION" });
  await assert.rejects(captureOriginalEndpoint(callback, socketPath), /cannot be rebound/);
  await assert.rejects(assertOriginalCandidateRetired(() => {}, [], "unbound"), /original callback endpoint capture/);
  const aborted = new AbortController();
  aborted.abort(new Error("original observer abort"));
  await assert.rejects(waitForOriginalEndpointRetirement(callback, aborted.signal), /original observer abort/);
  const retired = waitForOriginalEndpointRetirement(callback, t.signal);
  await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
  await retired;
  await assertOriginalCandidateRetired(callback, [], "closed");
  await new Promise((resolve, reject) => { server.once("error", reject); server.listen(socketPath, resolve); });
  await assert.rejects(assertOriginalCandidateRetired(callback, [], "replacement socket"), { code: "ERR_ASSERTION" });
  await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
  await writeFile(socketPath, "replacement is not retirement");
  await assert.rejects(assertOriginalCandidateRetired(callback, [], "replacement"), { code: "ERR_ASSERTION" });
  await assert.rejects(waitForOriginalEndpointRetirement(callback, t.signal), /replacement file/);
  await assert.rejects(captureOriginalEndpoint(() => {}, socketPath), /original live Unix endpoint/);
  await rm(socketPath);
  await assertOriginalCandidateRetired(callback, [], "replacement removed");
  await rm(directory, { recursive: true, force: true });
  await waitForOriginalEndpointRetirement(callback, t.signal);
});

test("candidate transport rejects missing non-socket and symlink endpoints before connection", async t => {
  const { callGoalCandidateTool } = await import("../../.tmp/unit/workflow-goal-workspace-tools.js");
  const directory = await mkdtemp(join(tmpdir(), "goal-transport-endpoint-"));
  const endpoint = join(directory, "candidate.sock"), linked = join(directory, "linked.sock");
  let connections = 0;
  const server = createUnixServer(socket => { connections++; socket.destroy(); });
  t.after(async () => {
    if (server.listening) await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
    await rm(directory, { recursive: true, force: true });
  });
  const read = socketPath => callGoalCandidateTool(
    { socketPath, secret: "NONAUTHORITY", hostKeyPin: "0".repeat(64), channelId: "NONAUTHORITY",
      attemptKey: "NONAUTHORITY", tools: ["goal_candidate_read"] },
    "missing-endpoint-probe", "goal_candidate_read", { path: "a.txt" });
  await assert.rejects(read(endpoint), { code: "ENOENT" });
  await writeFile(endpoint, "not a transport endpoint");
  await assert.rejects(read(endpoint), /Goal channel endpoint is not a Unix socket/);
  await rm(endpoint);
  await new Promise((resolve, reject) => { server.once("error", reject); server.listen(endpoint, resolve); });
  await symlink(endpoint, linked);
  await assert.rejects(read(linked), /Goal channel endpoint is not a Unix socket/);
  assert.equal(connections, 0, "no token or candidate request reaches an invalid endpoint");
});

test("repeated and concurrent stop requests preserve the original physical intent", async t => {
  const { requestWorkflowStop, workflowStopIntentPath } = await import("../../.tmp/unit/store.js");
  const cwd = await mkdtemp(join(tmpdir(), "goal-stop-intent-"));
  t.after(() => rm(cwd, { recursive: true, force: true }));
  const id = "workflow_original_stop";
  const first = await requestWorkflowStop(cwd, id);
  const path = workflowStopIntentPath(cwd, id);
  const bytes = await readFile(path), identity = await lstat(path);
  const concurrent = await Promise.all(Array.from({ length: 8 }, () => requestWorkflowStop(cwd, id)));
  assert.deepEqual(concurrent, Array.from({ length: 8 }, () => first));
  assert.deepEqual(await readFile(path), bytes);
  const retained = await lstat(path);
  assert.deepEqual([retained.dev, retained.ino], [identity.dev, identity.ino]);
  const contendedId = "workflow_concurrent_initial_stop";
  const initial = await Promise.all(Array.from({ length: 8 }, () => requestWorkflowStop(cwd, contendedId)));
  const committed = JSON.parse(await readFile(workflowStopIntentPath(cwd, contendedId), "utf8"));
  assert.deepEqual(initial, Array.from({ length: 8 }, () => committed));
  for (const invalid of [
    { ...first, runId: "workflow_foreign" },
    { ...first, requestedAt: null },
    { ...first, reason: "foreign" },
  ]) {
    const invalidBytes = JSON.stringify(invalid);
    await writeFile(path, invalidBytes);
    await assert.rejects(requestWorkflowStop(cwd, id), /Original workflow stop intent unavailable or invalid/);
    assert.equal(await readFile(path, "utf8"), invalidBytes);
  }
  await writeFile(path, "{");
  await assert.rejects(requestWorkflowStop(cwd, id), SyntaxError);
  assert.equal(await readFile(path, "utf8"), "{", "malformed original intent is not overwritten");
});

test("concurrent first stop publication preserves the winning bytes and inode", { timeout: testTimeoutMs(30_000) }, async t => {
  const { requestWorkflowStop, workflowStopIntentPath, setRunLeaseTestHooksForTests } =
    await import("../../.tmp/unit/store.js");
  const cwd = await mkdtemp(join(tmpdir(), "goal-stop-first-publication-"));
  const id = "workflow_first_stop_race", path = workflowStopIntentPath(cwd, id);
  const releases = [];
  let ready;
  const allPrepared = new Promise(resolve => { ready = resolve; });
  let released = false;
  const releaseAll = () => {
    released = true;
    for (const release of releases) release();
  };
  t.signal.addEventListener("abort", releaseAll, { once: true });
  t.after(async () => {
    releaseAll();
    setRunLeaseTestHooksForTests();
    t.signal.removeEventListener("abort", releaseAll);
    await rm(cwd, { recursive: true, force: true });
  });
  setRunLeaseTestHooksForTests({ onBeforeExclusiveLink: async ({ file }) => {
    if (file !== path || released) return;
    const held = new Promise(resolve => { releases.push(resolve); });
    if (releases.length === 8) ready();
    await held;
  } });
  const requests = Array.from({ length: 8 }, () => requestWorkflowStop(cwd, id));
  const completed = Promise.all(requests);
  let failure;
  try {
    await Promise.race([allPrepared, completed.then(() => assert.fail("first writers bypassed exclusive publication hook"))]);
    await assert.rejects(lstat(path), { code: "ENOENT" }, "all original writers are prepared before any publishes");
    releases[0]();
    const winner = await Promise.race(requests);
    const originalBytes = await readFile(path), originalIdentity = await lstat(path);
    assert.deepEqual(JSON.parse(originalBytes.toString("utf8")), winner);
    releaseAll();
    assert.deepEqual(await completed, Array.from({ length: 8 }, () => winner));
    assert.deepEqual(await readFile(path), originalBytes);
    const finalIdentity = await lstat(path);
    assert.deepEqual([finalIdentity.dev, finalIdentity.ino], [originalIdentity.dev, originalIdentity.ino],
      "seven losing first-create writers never replace the physical winner");
  } catch (error) {
    failure = error;
  } finally {
    releaseAll();
    const settled = await Promise.allSettled(requests);
    const errors = [...new Set([
      ...(failure === undefined ? [] : [failure]),
      ...settled.filter(result => result.status === "rejected").map(result => result.reason),
    ])];
    if (errors.length === 1) throw errors[0];
    if (errors.length > 1) throw new AggregateError(errors, "Original first-publication assertion and writer failures");
  }
});

test("original feedback stop and drain retains in-flight delivery and replacement ownership", { timeout: testTimeoutMs(30_000) }, async t => {
  // NONAUTHORITY: local terminal records exercise observer lifetime, not admission.
  const cwd = await mkdtemp(join(tmpdir(), "goal-feedback-drain-"));
  const runId = "original_feedback_drain", sessionId = "feedback-drain-session";
  const runDir = join(cwd, ".pi", "workflows", runId);
  const run = { schemaVersion: 1, runId, name: "feedback-drain", type: "artifact-graph", status: "completed", cwd,
    backend: { type: "local-pi", mode: "headless" }, createdAt: "2026-07-25T00:00:00.000Z", updatedAt: "2026-07-25T00:00:01.000Z",
    specPath: ".pi/workflows/spec.json",
    taskSummary: { total: 1, pending: 0, running: 0, blocked: 0, completed: 1, failed: 0, skipped: 0, interrupted: 0 },
    tasks: [{ taskId: "task-1", specId: "final", status: "completed", statusDetail: "completed", runtime: { model: "test-model", thinking: "none" },
      files: Object.fromEntries([["systemPrompt", "system.md"], ["taskPrompt", "task.md"], ["output", "output.log"], ["stderr", "stderr.log"], ["result", "result.json"]]
        .map(([key, file]) => [key, `.pi/workflows/${runId}/tasks/task-1/${file}`])) }] };
  await mkdir(join(runDir, "tasks", "task-1"), { recursive: true });
  await writeFile(join(runDir, "run.json"), JSON.stringify(run));
  await writeFile(join(runDir, "tasks", "task-1", "control.json"), "{}");
  await writeFile(join(runDir, "feedback-audience.json"), JSON.stringify({ schema: "workflow-feedback-audience-v1", runId, sessionId, boundAt: new Date().toISOString() }));
  const deferred = () => { let resolve; const promise = new Promise(done => { resolve = done; }); return { promise, resolve }; };
  const sends = [], notices = [], timers = [];
  const originalSetInterval = globalThis.setInterval, originalClearInterval = globalThis.clearInterval;
  const register = () => {
    // Capture only this observer's real interval callback; manually tick it,
    // without forcing delivery or changing any scheduling timeout.
    globalThis.setInterval = callback => { const timer = { callback, cleared: false, unref() {} }; timers.push(timer); return timer; };
    try { watchWorkflowFeedbackForTests(context, api, runId, new AbortController().signal); }
    finally { globalThis.setInterval = originalSetInterval; }
  };
  globalThis.clearInterval = timer => {
    if (timers.includes(timer)) timer.cleared = true;
    else originalClearInterval(timer);
  };
  const started = [deferred(), deferred()], release = [deferred(), deferred()];
  const context = { cwd, hasUI: true, sessionManager: { getSessionId: () => sessionId },
    ui: { confirm: async () => false, notify: (message, level) => notices.push({ message, level }) } };
  const api = { sendMessage(message) { const index = sends.length; sends.push(message); started[index].resolve(); return release[index].promise; } };
  t.after(async () => {
    release.forEach(gate => gate.resolve());
    try { await stopWorkflowFeedbackAndDrainForTests(cwd, runId); }
    finally { globalThis.setInterval = originalSetInterval; globalThis.clearInterval = originalClearInterval; await rm(cwd, { recursive: true, force: true }); }
  });
  await stopWorkflowFeedbackAndDrainForTests(cwd, "absent");
  assert.equal(sends.length, 0, "absent observer never invokes delivery");
  register();
  await stopWorkflowFeedbackAndDrainForTests(cwd, runId);
  assert.equal(timers[0].cleared, true);
  assert.equal(sends.length, 0, "idle observer drains without starting a poll");
  register();
  timers[1].callback();
  timers[1].callback();
  await started[0].promise;
  assert.equal(sends.length, 1, "original polling remains single-flight");
  let joined = false;
  const drain = stopWorkflowFeedbackAndDrainForTests(cwd, runId).then(() => { joined = true; });
  assert.equal(timers[1].cleared, true, "drain stops original timer synchronously");
  register();
  await stopWorkflowFeedbackAndDrainForTests(cwd, "unrelated");
  await stopWorkflowFeedbackAndDrainForTests(join(cwd, "unrelated"), runId);
  assert.equal(timers[2].cleared, false, "other cwd or run cannot stop replacement");
  assert.equal(joined, false, "held actual send prevents original drain settlement");
  assert.equal(notices.length, 0);
  release[0].resolve();
  await drain;
  assert.equal(notices.length, 1, "actual final notify precedes drain join");
  assert.equal(notices[0].level, "info");
  const receipts = await readdir(join(runDir, "feedback-delivery-receipts"));
  assert.equal(receipts.length, 1, "delivery.complete committed before drain join");
  assert.equal(JSON.parse(await readFile(join(runDir, "feedback-delivery-receipts", receipts[0]), "utf8")).status, "completed");
  assert.equal(timers[2].cleared, false, "old completion cannot delete replacement timer");
  run.tasks[0].completedAt = "2026-07-25T00:00:02.000Z";
  await writeFile(join(runDir, "run.json"), JSON.stringify(run));
  timers[2].callback();
  await started[1].promise;
  joined = false;
  const replacementDrain = stopWorkflowFeedbackAndDrainForTests(cwd, runId).then(() => { joined = true; });
  await stopWorkflowFeedbackAndDrainForTests(cwd, "unrelated");
  assert.equal(joined, false, "replacement retains its own in-flight custody");
  release[1].resolve();
  await replacementDrain;
  assert.equal(notices.length, 2);
  assert.deepEqual(notices.filter(({ level }) => level === "error"), []);
});

test("AC9 original SDK transport boundary rejects fetch but cannot enforce a throwing registered payload hook", async t => {
  // NONAUTHORITY: the original SDK/adapter runs, but its fetch is a local fixture.
  // This pins a missing product seam, not request-budget implementation or live qualification.
  const { DefaultResourceLoader, ModelRuntime, ModelRegistry,
    SettingsManager, SessionManager, ExtensionRunner } = await import("@earendil-works/pi-coding-agent");
  const { InMemoryCredentialStore } = await import("@earendil-works/pi-ai");
  const cwd = await mkdtemp(join(tmpdir(), "goal-original-transport-gap-"));
  t.after(() => rm(cwd, { recursive: true, force: true }));
  const modelRuntime = await ModelRuntime.create({
    credentials: new InMemoryCredentialStore(), modelsPath: null,
    allowModelNetwork: false, refreshOnCreate: false,
  });
  const registry = new ModelRegistry(modelRuntime);
  const original = registry.getProvider("openai");
  const model = original.getModels().find(value => value.api === "openai-responses");
  assert.ok(model, "locked original OpenAI HTTP adapter must be available without provisioning");
  let hookCalls = 0;
  const loader = new DefaultResourceLoader({ cwd, agentDir: cwd,
    settingsManager: SettingsManager.inMemory(), noExtensions: true, noSkills: true,
    noPromptTemplates: true, noThemes: true, noContextFiles: true,
    extensionFactories: [pi => pi.on("before_provider_request", () => {
      hookCalls++;
      throw new Error("NONAUTHORITY zero request reservation denied");
    })],
  });
  await loader.reload();
  const loaded = loader.getExtensions();
  assert.deepEqual(loaded.errors, []);
  const runner = new ExtensionRunner(loaded.extensions, loaded.runtime, cwd, SessionManager.inMemory(cwd), registry);
  const errors = [];
  runner.onError(error => errors.push({ event: error.event, error: error.error }));
  const context = { messages: [{ role: "user", content: "NONAUTHORITY fixture", timestamp: 1 }] };
  let intercepted = 0, physicalFixtureAttempts = 0, payload;
  const options = {
    apiKey: "NONAUTHORITY-fixture-only", maxRetries: 0,
    onPayload: async value => { payload = value; return runner.emitBeforeProviderRequest(value); },
    fetch: async (_url, init) => {
      intercepted++;
      assert.deepEqual(JSON.parse(init.body), JSON.parse(JSON.stringify(payload)),
        "hook failure must not poison or replace the serialized original payload");
      physicalFixtureAttempts++;
      throw new Error("NONAUTHORITY physical fixture endpoint reached");
    },
  };
  const result = await original.streamSimple(model, context, options).result();
  assert.equal(hookCalls, 1);
  assert.equal(intercepted, 1);
  assert.equal(physicalFixtureAttempts, 1,
    `throwing registered hook did NOT deny original adapter transmission: ${result.errorMessage}`);
  assert.deepEqual(errors, [{ event: "before_provider_request", error: "NONAUTHORITY zero request reservation denied" }]);
  assert.equal(result.stopReason, "error");
  assert.equal(registry.getProvider(model.provider), original, "no replacement provider registration or auth producer");
  for (const method of ["stream", "streamSimple"]) {
    await t.test(`original ${method} honors rejecting HTTP fetch before physical fixture effects`, async () => {
      intercepted = 0; physicalFixtureAttempts = 0;
      const blocked = await original[method](model, context, {
        apiKey: "NONAUTHORITY-fixture-only", maxRetries: 0,
        fetch: async () => { intercepted++; throw new Error("NONAUTHORITY preeffect reservation UNKNOWN"); },
      }).result();
      assert.equal(blocked.stopReason, "error");
      assert.equal(blocked.errorMessage, "Connection error.",
        "locked OpenAI SDK replaces the fetch denial message; UNKNOWN must remain in the original reservation journal");
      assert.equal(intercepted, 1, "real locked HTTP adapter invokes per-request fetch without retry");
      assert.equal(physicalFixtureAttempts, 0);
    });
  }
});

async function goalBudgetNativeFixture(cwd, extension, selected = "openai/gpt-5.1") {
  const sdk = await import("@earendil-works/pi-coding-agent");
  const { InMemoryCredentialStore } = await import("@earendil-works/pi-ai");
  const modelRuntime = await sdk.ModelRuntime.create({ credentials: new InMemoryCredentialStore(),
    modelsPath: null, allowModelNetwork: false, refreshOnCreate: false });
  const registry = new sdk.ModelRegistry(modelRuntime);
  const [provider, id] = selected.split("/");
  const model = registry.find(provider, id);
  assert.ok(model);
  const original = registry.getProvider(provider);
  const loader = new sdk.DefaultResourceLoader({ cwd, agentDir: cwd,
    settingsManager: sdk.SettingsManager.inMemory(), noExtensions: true, noSkills: true,
    noPromptTemplates: true, noThemes: true, noContextFiles: true,
    extensionFactories: [extension] });
  await loader.reload();
  const loaded = loader.getExtensions();
  assert.deepEqual(loaded.errors, []);
  const runner = new sdk.ExtensionRunner(loaded.extensions, loaded.runtime, cwd, sdk.SessionManager.inMemory(cwd), registry);
  const errors = [];
  runner.onError(error => errors.push(error));
  runner.bindCore({}, { getModel: () => model, getScopedModels: () => [], isIdle: () => true,
    isProjectTrusted: () => true, getSignal: () => undefined, abort() {}, hasPendingMessages: () => false,
    shutdown() {}, getContextUsage: () => undefined, compact() {}, getSystemPrompt: () => "" }, {
    registerNativeProvider: value => registry.registerProvider(value),
  });
  await runner.emit({ type: "session_start" });
  assert.deepEqual(errors, []);
  await registry.refresh({ allowNetwork: false });
  return { registry, model, original, modelRuntime, runner };
}

function goalBudgetSSE(usage = true, text, tokens = { input_tokens: 1, output_tokens: 1, total_tokens: 2 }) {
  const item = text === undefined ? undefined : { type: "message", id: "NONAUTHORITY-message", role: "assistant", status: "completed",
    content: [{ type: "output_text", text, annotations: [] }] };
  const events = item ? [
    { type: "response.output_item.added", output_index: 0, item: { ...item, content: [] } },
    { type: "response.output_text.delta", output_index: 0, content_index: 0, delta: text },
    { type: "response.output_item.done", output_index: 0, item },
  ] : [];
  events.push({ type: "response.completed", response: {
    id: "NONAUTHORITY-response", status: "completed", output: [],
    ...(usage ? { usage: tokens } : {}),
  } });
  return new Response(events.map(event => `data: ${JSON.stringify(event)}\n\n`).join(""), { status: 200, headers: { "content-type": "text/event-stream" } });
}

function goalBudgetToolCallsSSE(calls, tokens = { input_tokens: 1, output_tokens: 1, total_tokens: 2 }) {
  const events = calls.flatMap(({ id, name, arguments: args }, output_index) => {
    const item = { type: "function_call", id: `fc_${id}`, call_id: `call_${id}`, name,
      arguments: JSON.stringify(args), status: "completed" };
    return [
      { type: "response.output_item.added", output_index, item },
      { type: "response.output_item.done", output_index, item },
    ];
  });
  events.push({ type: "response.completed", response: {
    id: "NONAUTHORITY-tool-response", status: "completed", output: [],
    usage: tokens,
  } });
  return new Response(events.map(event => `data: ${JSON.stringify(event)}\n\n`).join(""),
    { status: 200, headers: { "content-type": "text/event-stream" } });
}

