  const tools = new Map();
  registerGoalCandidateTools({ registerTool(tool) { tools.set(tool.name, tool); }, on() {}, setActiveTools() {} }, channel.channel);
  const read = () => tools.get("goal_candidate_read").execute("read-census", { path: "a.txt" });
