      await writeFile(resolve(receipt.cwd, replacementRef), JSON.stringify(oracle));
      publication.retainedEvidenceRefs = publication.retainedEvidenceRefs.map(ref => ref === previousRef ? replacementRef : ref);
      await writeFile(publicationPath, JSON.stringify(publication));
