    const evidence = childParentProfileReservationTamper;
    const records = await listRunRecords(cwd);
    const actualParent = records.find(record => record.runId === evidence.parentRunId);
    const actualChild = records.find(record => record.runId === evidence.childRunId);
    assert.ok(actualParent && actualChild);
