function makeUiContext(cwd, messages) {
  return {
    cwd,
    hasUI: true,
    ui: {
      async select(_title, options) { return options[0]; },
      notify(message, level) {
        messages.push({ message, level });
      },
    },
  };
}

test("C01 C06 DP15 extension registration and empty read surfaces are inert", async () => {
  const cwd = await mkdtemp(join(tmpdir(), "goal-dp15-extension-"));
  const originalRole = process.env.PI_WORKFLOW_ROLE;
  let subagentApiReads = 0;
  try {
    process.env.PI_WORKFLOW_ROLE = "supervisor";
    setSubagentApiForTests(
      new Proxy(Object.create(null), {
        get() {
          subagentApiReads += 1;
          throw new Error("inert Goal read surface reached the worker API");
        },
      }),
    );
    const commands = new Map();
    const tools = [];
    const handlers = new Map();
    let goalProfileReads = 0;
    let modelMessages = 0;
    workflowExtension({
      on(event, handler) {
        handlers.set(event, handler);
      },
      registerCommand(name, definition) {
        commands.set(name, definition);
      },
      registerTool(tool) {
        tools.push(tool);
      },
      sendMessage() {
        modelMessages += 1;
      },
      getThinkingLevel() {
        goalProfileReads += 1;
        return undefined;
      },
    });

    assert.ok(
      commands.has("workflow"),
      "existing /workflow command remains registered",
    );
    assert.equal(commands.has("goal"), false, "standalone /goal command is not registered");
    assert.deepEqual(
      tools.map((tool) => tool.name),
      [
        WORKFLOW_LIST_TOOL,
        WORKFLOW_RUN_TOOL,
        WORKFLOW_DYNAMIC_TOOL,
        WORKFLOW_WAIT_TOOL,
        GOAL_TOOL,
      ],
    );
    assert.equal(existsSync(join(cwd, ".pi")), false);

    const messages = [];
    await commands.get("workflow").handler("goal help", makeUiContext(cwd, messages));
    assert.match(messages.at(-1).message, /workflow goal/);
    assert.equal(
      existsSync(join(cwd, ".pi")),
      false,
      "help does not create Goal namespace",
    );

    await commands.get("workflow").handler("goal list", makeUiContext(cwd, messages));
    assert.match(messages.at(-1).message, /No goals found/);
    assert.equal(
      existsSync(join(cwd, ".pi")),
      false,
      "empty list does not create Goal namespace",
    );

    // goal run without a definition or request explains the Goal command, not /workflow run.
    for (const [suffix, expected] of [
      ["run", /^Goal run needs a saved Goal definition and a request\. Usage: \/workflow goal run <definition> "<request>"/],
      ["run csv-parser", /^This Goal run needs a request\. Usage: \/workflow goal run <definition> "<request>"/],
    ]) {
      const base = makeUiContext(cwd, messages);
      const tui = { ...base, mode: "tui", ui: { ...base.ui, async input() { throw new Error("no prompt expected"); } } };
      const shown = await commands.get("workflow").handler(`goal ${suffix}`, tui)
        .then(() => messages.at(-1).message, error => error.message);
      assert.match(shown, expected, suffix);
      assert.doesNotMatch(shown, /\/workflow run <workflow/, suffix);
    }
    assert.equal(existsSync(join(cwd, ".pi")), false, "a refused goal run creates nothing");

    const goalTool = tools.find((tool) => tool.name === GOAL_TOOL);
    const schemaText = JSON.stringify(goalTool.parameters);
    assert.doesNotMatch(schemaText, /oneOf|anyOf|const/);
    assert.deepEqual(goalTool.parameters.properties.action.enum, [
      "list",
      "status",
      "criteria",
      "evidence",
    ]);
    const toolResult = await goalTool.execute(
      "tool-goal-list",
      { action: "list" },
      new AbortController().signal,
      undefined,
      { cwd },
    );
    assert.equal(toolResult.details.namespace, "ordinary-workflow-engine");
    assert.deepEqual(toolResult.details.runs, []);
    await assert.rejects(goalTool.execute(
      "tool-goal-create",
      { action: "create", request: "tool text is not actor authority" },
      new AbortController().signal,
      undefined,
      { cwd },
    ), /unknown fields/);
    assert.equal(
      existsSync(join(cwd, ".pi")),
      false,
      "model tool create cannot mint actor provenance or a namespace",
    );
    const allStatus = await goalTool.execute(
      "tool-goal-status-all",
      { action: "status" },
      new AbortController().signal,
      undefined,
      { cwd },
    );
    assert.equal(allStatus.details.namespace, "ordinary-workflow-engine");
    assert.deepEqual(allStatus.details.runs, []);
    assert.equal(
      existsSync(join(cwd, ".pi")),
      false,
      "tool list does not create Goal namespace",
    );
    assert.equal(
      goalProfileReads,
      0,
      "read-only and untrusted create routes do not capture a runtime profile",
    );
    assert.equal(
      subagentApiReads,
      0,
      "extension load and empty reads never inspect or call the worker API",
    );
    assert.equal(
      modelMessages,
      0,
      "extension load and empty reads never enqueue a model-visible message",
    );
    assert.equal(typeof handlers.get("session_start"), "function");
  } finally {
    setSubagentApiForTests(undefined);
    if (originalRole === undefined) delete process.env.PI_WORKFLOW_ROLE;
    else process.env.PI_WORKFLOW_ROLE = originalRole;
    await rm(cwd, { recursive: true, force: true });
  }
});
